import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';

const NAME_FIELD = 'Account.Name';
const INDUSTRY_FIELD = 'Account.Industry';
const ANNUAL_REVENUE_FIELD = 'Account.AnnualRevenue';
const OWNER_NAME_FIELD = 'Account.Owner.Name';

const ACCOUNT_FIELDS = [
    NAME_FIELD,
    INDUSTRY_FIELD,
    ANNUAL_REVENUE_FIELD,
    OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: ACCOUNT_FIELDS })
    record;

    get isLoading() {
        const result = this.record || {};
        return !result.data && !result.error;
    }

    get hasError() {
        return Boolean(this.record && this.record.error);
    }

    get errorMessage() {
        const result = this.record || {};
        const err = result.error;

        if (!err) {
            return '';
        }

        if (err.error) {
            return (
                (err.error.body && err.error.body.message) ||
                err.error.message ||
                ''
            );
        }

        return (err.body && err.body.message) || err.message || '';
    }

    get name() {
        const data = this.record && this.record.data;
        return data ? getFieldValue(data, NAME_FIELD) : '';
    }

    get industry() {
        const data = this.record && this.record.data;
        return data ? getFieldValue(data, INDUSTRY_FIELD) : '';
    }

    get annualRevenue() {
        const data = this.record && this.record.data;
        return data ? getFieldValue(data, ANNUAL_REVENUE_FIELD) : undefined;
    }

    get ownerName() {
        const data = this.record && this.record.data;
        return data ? getFieldValue(data, OWNER_NAME_FIELD) : '';
    }
}
