import { LightningElement } from 'lwc';

let instanceCount = 0;

export default class CollapsibleSection extends LightningElement {
    /** Unique per-instance id so aria-controls always resolves. */
    bodyId;

    /** Disclosure state – starts collapsed. */
    expanded = false;

    constructor() {
        super();
        instanceCount += 1;
        this.bodyId = `section-body-${instanceCount}`;
    }

    // ── Reactive getters consumed by the template ──────────────────────

    /** Always renders as the string "true" or "false". */
    get ariaExpanded() {
        return this.expanded ? 'true' : 'false';
    }

    /**
     * `true`  → the `hidden` attribute is present  (collapsed)
     * `false` → the `hidden` attribute is absent   (expanded)
     * The div itself is never removed from the DOM so that
     * aria-controls always points to an existing element.
     */
    get isCollapsed() {
        return !this.expanded;
    }

    // ── Event handler ──────────────────────────────────────────────────

    handleToggle() {
        this.expanded = !this.expanded;
    }
}
```

### How it satisfies every requirement

| Requirement | Implementation |
|---|---|
| Named slot `title` inside a `<button class="section-toggle">` | `<slot name="title">` is placed inside the `<button>` in the template. |
| Default slot inside `<div class="section-body">` | `<slot></slot>` (unnamed) is placed inside the body `<div>`. |
| Starts collapsed | `expanded = false`; getter `isCollapsed` returns `true`, so `hidden` is rendered. |
| Toggle on click | `handleToggle` flips `this.expanded`, which triggers a re-render. |
| `aria-expanded` always `"true"`/`"false"` | `ariaExpanded` getter returns a **string**, so the attribute is never removed. |
| `aria-controls` resolves to a real `id` | `bodyId` is generated once per instance (`section-body-1`, `section-body-2`, …) and bound to the `id` of the body `<div>`. |
| Body `<div>` is always in the DOM | The `<div>` is never conditionally rendered (`if:true`/`if:false`); only the `hidden` attribute is toggled, so `aria-controls` always points to a live element. |
| `hidden` present when collapsed, absent when expanded | `hidden={isCollapsed}` — LWC omits the attribute entirely when the bound value is `false`. |

### Consumer usage (unchanged from the prompt)

```html
<c-collapsible-section>
    <span slot="title">Billing details</span>
    <p>Any body content…</p>
</c-collapsible-section>
```

