import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    results = [];
    error;

    /** Debounce timer id */
    _timeout;
    /** Monotonically-increasing token for in-flight requests */
    _requestId = 0;
    /** True once the component has been removed from the DOM */
    _destroyed = false;

    handleSearch(event) {
        // Cancel any pending debounced search
        clearTimeout(this._timeout);

        const trimmed = event.target.value.trim();

        // Fewer than 2 characters → cancel, no Apex call, clear results
        if (trimmed.length < 2) {
            this.results = [];
            this.error = undefined;
            return;
        }

        // Schedule (or reschedule) the imperative call after 300 ms
        this._timeout = setTimeout(() => {
            this._performSearch(trimmed);
        }, 300);
    }

    _performSearch(searchTerm) {
        const currentRequestId = ++this._requestId;

        searchContacts({ searchTerm })
            .then(result => {
                // Ignore if component is gone or a newer request superseded this one
                if (this._destroyed || this._requestId !== currentRequestId) {
                    return;
                }
                this.error = undefined;
                this.results = result;
            })
            .catch(error => {
                if (this._destroyed || this._requestId !== currentRequestId) {
                    return;
                }
                this.results = [];
                this.error =
                    error && error.body && error.body.message
                        ? error.body.message
                        : 'An error occurred.';
            });
    }

    disconnectedCallback() {
        this._destroyed = true;
        clearTimeout(this._timeout);
    }
}
