import { LightningElement, api, track } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    @track isLoading = false;
    @track error = null;
    @track opportunities = null;

    connectedCallback() {
        if (this.recordId) {
            this.loadOpportunities();
        }
    }

    handleRetry = () => {
        this.loadOpportunities();
    };

    loadOpportunities = () => {
        if (this.isLoading || !this.recordId) {
            return;
        }

        this.isLoading = true;
        this.error = null;
        this.opportunities = null;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result || [];
                this.error = null;
            })
            .catch((err) => {
                this.error = err;
                this.opportunities = null;
            })
            .finally(() => {
                this.isLoading = false;
            });
    };

    get errorMessage() {
        if (this.error && this.error.body && this.error.body.message) {
            return this.error.body.message;
        }

        if (this.error && this.error.message) {
            return this.error.message;
        }

        return 'An error occurred.';
    }

    get hasError() {
        return !this.isLoading && Boolean(this.error);
    }

    get hasOpportunities() {
        return (
            !this.isLoading &&
            !this.error &&
            Array.isArray(this.opportunities) &&
            this.opportunities.length > 0
        );
    }

    get isEmpty() {
        return (
            !this.isLoading &&
            !this.error &&
            Array.isArray(this.opportunities) &&
            this.opportunities.length === 0
        );
    }
}
