import { LightningElement, track } from 'lwc';
import { getQueueStats } from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL = 60000;

export default class QueueMonitor extends LightningElement {
    @track waiting = null;
    @track longestWaitMinutes = null;
    @track error = null;
    @track isLoading = false;

    _intervalId = null;
    _handleVisibilityChange = null;

    // ─── Lifecycle ───────────────────────────────────────────────────────────

    connectedCallback() {
        this._handleVisibilityChange = () => {
            // Component may have been disconnected while event was queued
            if (!this.isConnected) return;

            if (document.visibilityState === 'visible') {
                // Page just became visible: load immediately and resume polling
                this._stopPolling();
                this._loadStats();
                this._startPolling();
            } else {
                // Page is hidden: stop polling entirely – no requests while hidden
                this._stopPolling();
            }
        };

        document.addEventListener('visibilitychange', this._handleVisibilityChange);

        // Initial load + start the recurring poll
        this._loadStats();
        this._startPolling();
    }

    disconnectedCallback() {
        this._stopPolling();

        if (this._handleVisibilityChange) {
            document.removeEventListener(
                'visibilitychange',
                this._handleVisibilityChange
            );
            this._handleVisibilityChange = null;
        }
    }

    // ─── Polling helpers ─────────────────────────────────────────────────────

    _startPolling() {
        this._stopPolling(); // guarantee at most one interval per component
        this._intervalId = setInterval(() => {
            // Guard against the timer firing in a hidden tab (belt + suspenders)
            if (document.visibilityState === 'hidden') return;
            this._loadStats();
        }, POLL_INTERVAL);
    }

    _stopPolling() {
        if (this._intervalId != null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    // ─── Data loading ────────────────────────────────────────────────────────

    async _loadStats() {
        // Never overlap: skip if a request is already in flight
        if (this.isLoading) return;

        this.isLoading = true;

        try {
            const result = await getQueueStats();

            // If the component was torn down while the call was in flight, bail
            if (!this.isConnected) return;

            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.error = null; // clear any prior error on success
        } catch (e) {
            if (!this.isConnected) return;

            const msg =
                (e && e.body && typeof e.body === 'object'
                    ? e.body.message
                    : e && e.body) || 'Unknown error';
            this.error = msg;
            // Keep old stats out of the view; show the error instead
            this.waiting = null;
            this.longestWaitMinutes = null;
        }

        this.isLoading = false;
    }
}
