import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    formData = { fullName: '', email: '', company: '' };

    handleFieldChange(event) {
        const field = event.target.dataset.field;
        if (field) {
            this.formData = { ...this.formData, [field]: event.detail.value };
        }
    }

    handleRegister(event) {
        // Step 1: Check email domain for personal addresses
        const emailInput = this.template.querySelector('[data-field="email"]');
        if (emailInput) {
            const email = this.formData.email;
            const domain = email ? email.split('@')[1]?.toLowerCase() : '';
            if (PERSONAL_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // Step 2: Call reportValidity on every input so all errors show at once
        const inputs = this.template.querySelectorAll('lightning-input');
        let isValid = true;
        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                isValid = false;
            }
        });

        // Step 3: If any input is invalid, stop
        if (!isValid) {
            return;
        }

        // Call register imperatively
        register({
            fullName: this.formData.fullName,
            email: this.formData.email,
            company: this.formData.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        variant: 'error',
                        message: error.body.message
                    })
                );
            });
    }
}
