import { LightningElement, api, track } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    @track _activeIndex = 0;
    @track _currentValue = '';
    _opts = [];
    _uid = '';
    _label = '';

    constructor() {
        super();
        instanceCount += 1;
        this._uid = `slb-${instanceCount}`;
    }

    // ── Public API ──────────────────────────────────────────────────────────

    @api
    get label() {
        return this._label;
    }
    set label(v) {
        this._label = v;
    }

    @api
    get options() {
        return this._opts;
    }
    set options(v) {
        this._opts = v || [];
        this._recalc();
    }

    @api
    get value() {
        return this._currentValue;
    }
    set value(v) {
        this._currentValue = v || '';
        this._recalc();
    }

    // ── Internal helpers ────────────────────────────────────────────────────

    _recalc() {
        const idx = this._opts.findIndex((o) => o.value === this._currentValue);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    // ── Template bindings ───────────────────────────────────────────────────

    get activeDescendantId() {
        if (!this._opts || this._opts.length === 0) {
            return undefined;
        }
        return `${this._uid}-opt-${this._activeIndex}`;
    }

    get renderOptions() {
        if (!this._opts || this._opts.length === 0) {
            return [];
        }
        return this._opts.map((opt, i) => ({
            value: opt.value,
            label: opt.label,
            id: `${this._uid}-opt-${i}`,
            index: i,
            ariaSelected: opt.value === this._currentValue ? 'true' : 'false',
        }));
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    handleKeyDown(event) {
        const { key } = event;
        const len = this._opts.length;
        if (len === 0) return;

        let handled = false;

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < len - 1) {
                    this._activeIndex += 1;
                }
                handled = true;
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex -= 1;
                }
                handled = true;
                break;
            case 'Home':
                this._activeIndex = 0;
                handled = true;
                break;
            case 'End':
                this._activeIndex = len - 1;
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this._selectActive();
                handled = true;
                break;
            default:
                break;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleClick(event) {
        const li = event.target.closest('[role="option"]');
        if (!li) return;

        const index = parseInt(li.dataset.index, 10);
        if (Number.isNaN(index) || index < 0 || index >= this._opts.length) return;

        this._activeIndex = index;
        const opt = this._opts[index];
        this._selectOption(opt.value);
    }

    // ── Selection logic ─────────────────────────────────────────────────────

    _selectActive() {
        const opt = this._opts[this._activeIndex];
        if (!opt) return;
        this._selectOption(opt.value);
    }

    _selectOption(value) {
        if (value === this._currentValue) return;

        this._currentValue = value;
        const idx = this._opts.findIndex((o) => o.value === value);
        if (idx >= 0) {
            this._activeIndex = idx;
        }

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true,
            })
        );
    }
}
