import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading;

    @api
    get heading() {
        return (this._heading || '').toUpperCase();
    }
    set heading(value) {
        this._heading = value;
    }

    @api
    get tasks() {
        return this.items;
    }
    set tasks(value) {
        if (Array.isArray(value)) {
            this.items = value.map((t) => ({ ...t }));
        } else {
            this.items = [];
        }
    }

    items = [];
    newLabel = '';
    nextId = 1;

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        const newTask = { id: `new-${this.nextId++}`, label, done: false };
        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', { detail: { label } })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
